    print('single-tuple works:', a, a.codon, a.aa)
except Exception as e:
    print('single-tuple FAILS:', repr(e))
try:
    b = N('AUG', 'methionine')
    print('two-args works:', b, b.codon, b.aa)
except Exception as e:
    print('two-args FAILS:', repr(e))
try:
    c = N((('AUG', 'methionine'),))
    print('single tuple-of-tuple works:', c, c.codon, c.aa)
except Exception as e:
    print('tuple-of-tuple FAILS:', repr(e))
